__hydrateVak("vmbo","ec",{"A":{"sv":[{"v":"Wat betekent koopkracht?","o":["Wat je kunt kopen","Wat je totaal spaart","Wat je totaal leent","Wat je aan belasting betaalt"],"c":0,"d":1,"u":"Wat je met je inkomen kunt kopen.","uo":["Klopt: wat je met je inkomen kunt kopen.","Sparen is iets anders.","Lenen is iets anders.","Belasting is iets anders."],"uh":"Wat je met je inkomen kunt kopen."},{"v":"Wat gebeurt er bij inflatie?","o":["De prijzen dalen","De prijzen stijgen","De lonen dalen mee","Het geld verdwijnt"],"c":1,"d":2,"u":"Bij inflatie stijgen de prijzen.","uo":["Dat is deflatie.","Klopt: bij inflatie stijgen de prijzen.","Lonen dalen niet automatisch.","Geld verdwijnt niet."],"uh":"Bij inflatie stijgen de prijzen."},{"v":"Wat is een indexcijfer?","o":["Een soort belasting","Een spaarrekening","Een getal dat een verandering toont","Een muntsoort"],"c":2,"d":1,"u":"Een verandering ten opzichte van een basisjaar (100).","uo":["Geen belasting.","Geen spaarrekening.","Klopt: een verandering ten opzichte van een basisjaar (100).","Geen muntsoort."],"uh":"Een verandering ten opzichte van een basisjaar (100)."},{"v":"Waarvoor betaal je premie?","o":["Voor een lening","Voor belasting","Voor sparen","Voor een verzekering"],"c":3,"d":1,"u":"Premie betaal je voor een verzekering.","uo":["Een lening betaal je met rente terug.","Belasting is iets anders.","Sparen kost geen premie.","Klopt: premie betaal je voor een verzekering."],"uh":"Premie betaal je voor een verzekering."},{"v":"Wat is je eigen risico bij een verzekering?","o":["Het deel dat je zelf betaalt","De premie per maand","De totale schade","Het spaargeld"],"c":0,"d":2,"u":"Het deel van de schade dat je zelf betaalt.","uo":["Klopt: het deel van de schade dat je zelf betaalt.","Dat is de premie.","De verzekeraar dekt de rest.","Sparen is iets anders."],"uh":"Het deel van de schade dat je zelf betaalt."},{"v":"Je prijzen stijgen 5%, je loon 2%. Wat gebeurt met je koopkracht?","o":["Die stijgt","Die daalt","Die blijft gelijk","Die verdwijnt"],"c":1,"d":3,"u":"Je koopkracht daalt.","uo":["Nee, de prijzen stijgen harder.","Klopt: je koopkracht daalt.","Nee, er is een verschil.","Koopkracht verdwijnt niet."],"uh":"Je koopkracht daalt."},{"v":"Wat is het verschil tussen sparen en uitgeven?","o":["Sparen kost meer","Beide zijn hetzelfde","Sparen bewaar je, uitgeven besteed je","Uitgeven is verboden"],"c":2,"d":2,"u":"Sparen bewaar je, uitgeven besteed je.","uo":["Sparen kost niets extra.","Ze zijn niet hetzelfde.","Klopt: sparen bewaar je, uitgeven besteed je.","Uitgeven mag gewoon."],"uh":"Sparen bewaar je, uitgeven besteed je."},{"v":"Wat is een budget?","o":["Een soort belasting","Een verzekering","Een lening","Een overzicht van inkomsten en uitgaven"],"c":3,"d":1,"u":"Een overzicht van inkomsten en uitgaven.","uo":["Geen belasting.","Geen verzekering.","Geen lening.","Klopt: een overzicht van inkomsten en uitgaven."],"uh":"Een overzicht van inkomsten en uitgaven."},{"v":"Wat is reëel inkomen?","o":["Inkomen na inflatie","Inkomen in euro's","Je spaargeld","Je uitgaven"],"c":0,"d":2,"u":"Inkomen gecorrigeerd voor inflatie.","uo":["Klopt: inkomen gecorrigeerd voor inflatie.","Dat is nominaal inkomen.","Sparen is iets anders.","Uitgaven zijn iets anders."],"uh":"Inkomen gecorrigeerd voor inflatie."},{"v":"Wat betekent deflatie?","o":["Prijzen stijgen","Prijzen dalen","Lonen stijgen","Belasting stijgt"],"c":1,"d":1,"u":"Bij deflatie dalen de prijzen.","uo":["Dat is inflatie.","Klopt: bij deflatie dalen de prijzen.","Lonen zijn iets anders.","Belasting is iets anders."],"uh":"Bij deflatie dalen de prijzen."},{"v":"Waarom sluit je een verzekering af?","o":["Om te sparen","Om te lenen","Om je te beschermen tegen grote kosten","Om belasting te betalen"],"c":2,"d":2,"u":"Bescherming tegen grote onverwachte kosten.","uo":["Sparen is iets anders.","Lenen is iets anders.","Klopt: bescherming tegen grote onverwachte kosten.","Belasting is iets anders."],"uh":"Bescherming tegen grote onverwachte kosten."},{"v":"Wat is nominaal inkomen?","o":["Inkomen na inflatie","Je koopkracht","Je spaargeld","Inkomen in euro's"],"c":3,"d":2,"u":"Inkomen in euro's, zonder correctie.","uo":["Dat is reëel inkomen.","Koopkracht is iets anders.","Sparen is iets anders.","Klopt: inkomen in euro's, zonder correctie."],"uh":"Inkomen in euro's, zonder correctie."},{"v":"Wat is budgetteren?","o":["Je uitgaven plannen","Meer geld lenen","Alles snel uitgeven","Belasting ontwijken"],"c":0,"d":1,"u":"Je uitgaven plannen binnen je inkomen.","uo":["Klopt: je uitgaven plannen binnen je inkomen.","Lenen is iets anders.","Dat is het tegenovergestelde.","Dat mag niet."],"uh":"Je uitgaven plannen binnen je inkomen."},{"v":"Wat is nodig voor meer koopkracht?","o":["Prijzen die veel harder stijgen dan lonen","Loon dat harder stijgt dan de prijzen","Meer lenen bij de bank","Hogere belasting betalen"],"c":1,"d":3,"u":"Je loon stijgt harder dan de prijzen.","uo":["Dan daalt je koopkracht juist.","Klopt: je loon stijgt harder dan de prijzen.","Lenen helpt niet blijvend.","Hogere belasting helpt niet."],"uh":"Je loon stijgt harder dan de prijzen."}],"begrippen":[{"t":"Koopkracht","d":"hoeveel je met je inkomen kunt kopen"},{"t":"Inkomen","d":"het geld dat je ontvangt, bijvoorbeeld loon"},{"t":"Uitgaven","d":"het geld dat je besteedt"},{"t":"Sparen","d":"geld dat je niet uitgeeft maar bewaart"},{"t":"Budget","d":"een overzicht van verwachte inkomsten en uitgaven"},{"t":"Budgetteren","d":"je uitgaven plannen binnen je inkomen"},{"t":"Inflatie","d":"een algemene stijging van de prijzen"},{"t":"Deflatie","d":"een algemene daling van de prijzen"},{"t":"Indexcijfer","d":"een getal dat een verandering ten opzichte van een basisjaar weergeeft"},{"t":"Reëel inkomen","d":"je inkomen gecorrigeerd voor inflatie"},{"t":"Nominaal inkomen","d":"je inkomen in euro's zonder correctie voor inflatie"},{"t":"Verzekering","d":"een afspraak waarbij je premie betaalt tegen financiële risico's"},{"t":"Premie","d":"het bedrag dat je periodiek voor een verzekering betaalt"},{"t":"Eigen risico","d":"het deel van de schade dat je zelf betaalt"}],"sam":"<div class=\"sam-intro\"><strong>Koopkracht</strong> is hoeveel je met je inkomen kunt kopen. Door <strong>inflatie</strong> daalt je koopkracht als je loon niet meestijgt. Met een <strong>indexcijfer</strong> reken je veranderingen uit, en met een <strong>verzekering</strong> bescherm je je tegen financiële risico's.</div><div class=\"sam-head\">1. Inkomen, uitgaven en koopkracht</div><p>Je <strong>inkomen</strong> is het geld dat je ontvangt, je <strong>uitgaven</strong> is het geld dat je besteedt. Wat je niet uitgeeft, kun je <strong>sparen</strong>. Met een <strong>budget</strong> (een overzicht van inkomsten en uitgaven) hou je overzicht; <strong>budgetteren</strong> is je uitgaven vooraf plannen.</p><p>Je <strong>koopkracht</strong> zegt hoeveel je met dat inkomen daadwerkelijk kunt kopen.</p><div class=\"sam-head\">2. Inflatie en je koopkracht</div><p><strong>Inflatie</strong> is een algemene stijging van de prijzen, <strong>deflatie</strong> een daling. Een <strong>indexcijfer</strong> laat een verandering zien ten opzichte van een basisjaar (dat op 100 staat).</p><p>Je <strong>nominaal inkomen</strong> is je inkomen in euro's; je <strong>reëel inkomen</strong> is dat inkomen gecorrigeerd voor inflatie. Stijgen de prijzen harder dan je loon, dan daalt je koopkracht.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">De prijzen stijgen met 4% (indexcijfer 104). Je loon stijgt met 2%. Wat gebeurt er met je koopkracht?</div><ol class=\"sam-worked-steps\"><li>Vergelijk de stijging van de prijzen met die van je loon.</li><li>De prijzen stijgen harder (4%) dan je loon (2%).</li></ol><div class=\"sam-worked-ans\">✅ Je koopkracht daalt: je kunt minder kopen dan eerst.</div></div><div class=\"sam-head\">3. Je beschermen met een verzekering</div><p>Een <strong>verzekering</strong> beschermt je tegen grote, onverwachte kosten. Je betaalt daarvoor periodiek een <strong>premie</strong>. Bij schade betaal je vaak eerst zelf een deel, het <strong>eigen risico</strong>; de rest vergoedt de verzekeraar.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Koopkracht</div><div class=\"sam-definitie-body\">hoeveel je met je inkomen kunt kopen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkomen</div><div class=\"sam-definitie-body\">het geld dat je ontvangt, bijvoorbeeld loon.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitgaven</div><div class=\"sam-definitie-body\">het geld dat je besteedt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sparen</div><div class=\"sam-definitie-body\">geld dat je niet uitgeeft maar bewaart.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Budget</div><div class=\"sam-definitie-body\">een overzicht van verwachte inkomsten en uitgaven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Budgetteren</div><div class=\"sam-definitie-body\">je uitgaven plannen binnen je inkomen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inflatie</div><div class=\"sam-definitie-body\">een algemene stijging van de prijzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Deflatie</div><div class=\"sam-definitie-body\">een algemene daling van de prijzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Indexcijfer</div><div class=\"sam-definitie-body\">een getal dat een verandering ten opzichte van een basisjaar weergeeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reëel inkomen</div><div class=\"sam-definitie-body\">je inkomen gecorrigeerd voor inflatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nominaal inkomen</div><div class=\"sam-definitie-body\">je inkomen in euro's zonder correctie voor inflatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verzekering</div><div class=\"sam-definitie-body\">een afspraak waarbij je premie betaalt tegen financiële risico's.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Premie</div><div class=\"sam-definitie-body\">het bedrag dat je periodiek voor een verzekering betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Eigen risico</div><div class=\"sam-definitie-body\">het deel van de schade dat je zelf betaalt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Koopkracht»</b> is wat je inkomen kan kopen, terwijl <b>«Reëel inkomen»</b> inkomen na inflatie is. <b>«Inkomen»</b> is geld dat je ontvangt, terwijl <b>«Uitgaven»</b> geld dat je besteedt is. <b>«Sparen»</b> is geld bewaren, terwijl <b>«Uitgaven»</b> geld dat je besteedt is. <b>«Budget»</b> is overzicht inkomsten en uitgaven, terwijl <b>«Budgetteren»</b> uitgaven plannen is.</div>"},"B":{"sv":[{"v":"Wat geeft garantie je recht op?","o":["Een lager bedrag","Herstel of vervanging bij een gebrek","Gratis producten","Meer bedenktijd"],"c":1,"d":2,"u":"Herstel of vervanging bij een gebrek.","uo":["Garantie gaat niet over korting.","Klopt: herstel of vervanging bij een gebrek.","Niet zomaar gratis.","Dat is iets anders."],"uh":"Herstel of vervanging bij een gebrek."},{"v":"Je koopt online een jas. Welk recht heb je?","o":["Geen enkel recht","Alleen garantie","Bedenktijd om te retourneren","Altijd gratis verzending"],"c":2,"d":2,"u":"Bij online kopen heb je bedenktijd.","uo":["Je hebt wel rechten.","Er is meer dan garantie.","Klopt: bij online kopen heb je bedenktijd.","Verzending is niet gegarandeerd gratis."],"uh":"Bij online kopen heb je bedenktijd."},{"v":"Wat doet de Consumentenbond?","o":["Producten testen en adviseren","Belasting innen","Geld uitlenen","Producten maken"],"c":0,"d":1,"u":"Test producten en geeft advies.","uo":["Klopt: test producten en geeft advies.","Dat doet de Belastingdienst.","Dat doet een bank.","Dat doet een fabriek."],"uh":"Test producten en geeft advies."},{"v":"Wat laat een keurmerk zien?","o":["De prijs","De maker","De houdbaarheid","Dat het aan eisen voldoet"],"c":3,"d":2,"u":"Dat een product aan bepaalde eisen voldoet.","uo":["Niet de prijs.","Niet de maker.","Niet per se de houdbaarheid.","Klopt: dat een product aan bepaalde eisen voldoet."],"uh":"Dat een product aan bepaalde eisen voldoet."},{"v":"Wat is een koopovereenkomst?","o":["Een verzekering","De afspraak tussen koper en verkoper","Een lening","Een belasting"],"c":1,"d":1,"u":"De afspraak tussen koper en verkoper.","uo":["Geen verzekering.","Klopt: de afspraak tussen koper en verkoper.","Geen lening.","Geen belasting."],"uh":"De afspraak tussen koper en verkoper."},{"v":"Je product is na een week kapot. Wat doe je?","o":["Niets, pech gehad","Er nog een kopen","Een klacht indienen","Belasting betalen"],"c":2,"d":3,"u":"Een klacht indienen bij de verkoper.","uo":["Je hebt rechten.","Dat helpt niet.","Klopt: een klacht indienen bij de verkoper.","Niet relevant."],"uh":"Een klacht indienen bij de verkoper."},{"v":"Wat is bedenktijd?","o":["Tijd om een aankoop te annuleren","Tijd om te sparen","Tijd om te lenen","Tijd om belasting te betalen"],"c":0,"d":1,"u":"De periode om een aankoop te annuleren.","uo":["Klopt: de periode om een aankoop te annuleren.","Sparen is iets anders.","Lenen is iets anders.","Belasting is iets anders."],"uh":"De periode om een aankoop te annuleren."},{"v":"Wat zijn algemene voorwaarden?","o":["De prijs van een product","Een soort verzekering","Een keurmerk","De regels bij een koop"],"c":3,"d":2,"u":"De regels die bij een koopovereenkomst horen.","uo":["Niet de prijs.","Geen verzekering.","Geen keurmerk.","Klopt: de regels die bij een koopovereenkomst horen."],"uh":"De regels die bij een koopovereenkomst horen."},{"v":"Wat is een consument?","o":["Een fabriek","Iemand die koopt en gebruikt","Een verkoper","De overheid"],"c":1,"d":1,"u":"Iemand die producten koopt en gebruikt.","uo":["Een fabriek maakt producten.","Klopt: iemand die producten koopt en gebruikt.","Een verkoper verkoopt juist.","De overheid is iets anders."],"uh":"Iemand die producten koopt en gebruikt."},{"v":"Waarvoor kun je bij de Consumentenbond terecht?","o":["Voor een lening","Voor belasting","Voor advies over producten","Voor een baan"],"c":2,"d":2,"u":"Voor advies en tests over producten.","uo":["Dat doet een bank.","Dat doet de Belastingdienst.","Klopt: voor advies en tests over producten.","Dat is iets anders."],"uh":"Voor advies en tests over producten."},{"v":"Wat is een aankoop op afstand?","o":["Kopen via internet of telefoon","Kopen in de winkel","Ruilen met een vriend","Iets huren"],"c":0,"d":1,"u":"Kopen zonder in de winkel te zijn.","uo":["Klopt: kopen zonder in de winkel te zijn.","Dat is juist in de winkel.","Ruilen is iets anders.","Huren is iets anders."],"uh":"Kopen zonder in de winkel te zijn."},{"v":"Waarom zijn consumentenrechten belangrijk?","o":["Ze verhogen de prijs","Ze innen belasting","Ze maken producten","Ze beschermen de koper"],"c":3,"d":3,"u":"Ze beschermen de koper.","uo":["Ze gaan niet over de prijs.","Niet over belasting.","Ze maken geen producten.","Klopt: ze beschermen de koper."],"uh":"Ze beschermen de koper."}],"begrippen":[{"t":"Consumentenrecht","d":"de rechten die een koper heeft"},{"t":"Garantie","d":"het recht op herstel of vervanging bij een gebrek"},{"t":"Retourrecht","d":"het recht om een aankoop terug te sturen"},{"t":"Bedenktijd","d":"de periode waarin je een aankoop mag annuleren"},{"t":"Consumentenorganisatie","d":"een organisatie die opkomt voor kopers"},{"t":"Consumentenbond","d":"een organisatie die producten test en consumenten adviseert"},{"t":"Klacht","d":"een melding dat een product of dienst niet voldoet"},{"t":"Keurmerk","d":"een teken dat een product aan bepaalde eisen voldoet"},{"t":"Algemene voorwaarden","d":"de regels die bij een koopovereenkomst horen"},{"t":"Koopovereenkomst","d":"de afspraak tussen een koper en een verkoper"},{"t":"Aankoop op afstand","d":"een aankoop via internet, telefoon of post"},{"t":"Consument","d":"iemand die producten of diensten koopt en gebruikt"}],"sam":"<div class=\"sam-intro\">Als koper heb je <strong>consumentenrechten</strong>, zoals <strong>garantie</strong> en bij online kopen een <strong>bedenktijd</strong>. Een <strong>consumentenorganisatie</strong> test producten en helpt bij een <strong>klacht</strong>.</div><div class=\"sam-head\">1. Je rechten als koper</div><p>Bij een aankoop sluit je een <strong>koopovereenkomst</strong>, waarbij <strong>algemene voorwaarden</strong> horen. <strong>Garantie</strong> geeft je recht op herstel of vervanging bij een gebrek. Koop je op afstand (online), dan heb je <strong>bedenktijd</strong> en een <strong>retourrecht</strong> om de aankoop terug te sturen.</p><div class=\"sam-head\">2. Hulp en keurmerken</div><p>Een <strong>consumentenorganisatie</strong> zoals de <strong>Consumentenbond</strong> test producten en geeft advies. Ben je ontevreden, dan dien je een <strong>klacht</strong> in bij de verkoper. Een <strong>keurmerk</strong> laat vooraf zien dat een product aan bepaalde eisen voldoet.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentenrecht</div><div class=\"sam-definitie-body\">de rechten die een koper heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Garantie</div><div class=\"sam-definitie-body\">het recht op herstel of vervanging bij een gebrek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Retourrecht</div><div class=\"sam-definitie-body\">het recht om een aankoop terug te sturen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bedenktijd</div><div class=\"sam-definitie-body\">de periode waarin je een aankoop mag annuleren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentenorganisatie</div><div class=\"sam-definitie-body\">een organisatie die opkomt voor kopers.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentenbond</div><div class=\"sam-definitie-body\">een organisatie die producten test en consumenten adviseert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Klacht</div><div class=\"sam-definitie-body\">een melding dat een product of dienst niet voldoet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Keurmerk</div><div class=\"sam-definitie-body\">een teken dat een product aan bepaalde eisen voldoet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Algemene voorwaarden</div><div class=\"sam-definitie-body\">de regels die bij een koopovereenkomst horen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Koopovereenkomst</div><div class=\"sam-definitie-body\">de afspraak tussen een koper en een verkoper.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Aankoop op afstand</div><div class=\"sam-definitie-body\">een aankoop via internet, telefoon of post.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consument</div><div class=\"sam-definitie-body\">iemand die producten of diensten koopt en gebruikt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Consumentenrecht»</b> is rechten van de koper, terwijl <b>«Garantie»</b> herstel bij een gebrek is. <b>«Garantie»</b> is herstel bij een gebrek, terwijl <b>«Retourrecht»</b> aankoop terugsturen is. <b>«Retourrecht»</b> is aankoop terugsturen, terwijl <b>«Bedenktijd»</b> periode om te annuleren is. <b>«Consumentenorganisatie»</b> is komt op voor kopers, terwijl <b>«Consumentenbond»</b> test en adviseert is.</div>"},"C":{"sv":[{"v":"Wat is je brutoloon?","o":["Je loon na aftrek","Je loon vóór aftrek","Je spaargeld","Je uitkering"],"c":1,"d":1,"u":"Je loon vóór aftrek van belasting en premies.","uo":["Dat is nettoloon.","Klopt: je loon vóór aftrek van belasting en premies.","Sparen is iets anders.","Een uitkering is iets anders."],"uh":"Je loon vóór aftrek van belasting en premies."},{"v":"Wat blijft over na aftrek van belasting en premies?","o":["Het brutoloon","De loonheffing","Het nettoloon","De cao"],"c":2,"d":2,"u":"Het nettoloon.","uo":["Dat is juist vóór aftrek.","Dat wordt juist ingehouden.","Klopt: het nettoloon.","Een cao is een afspraak."],"uh":"Het nettoloon."},{"v":"Wat is loonheffing?","o":["Belasting en premies op je loon","Je spaarrente","Je vakantiegeld","Je bonus"],"c":0,"d":1,"u":"Belasting en premies die worden ingehouden.","uo":["Klopt: belasting en premies die worden ingehouden.","Rente is iets anders.","Vakantiegeld is iets anders.","Een bonus is iets anders."],"uh":"Belasting en premies die worden ingehouden."},{"v":"Wat is arbeidsverdeling?","o":["Iedereen doet alles","Niemand werkt","Alleen de baas werkt","Werk in aparte taken opdelen"],"c":3,"d":3,"u":"Het werk in aparte taken opsplitsen.","uo":["Dat is juist het tegenovergestelde.","Onjuist.","Onjuist.","Klopt: het werk in aparte taken opsplitsen."],"uh":"Het werk in aparte taken opsplitsen."},{"v":"Wat gebeurt er door specialisatie?","o":["Mensen worden luier","Werk gaat sneller en beter","Er is minder werk","De lonen dalen mee"],"c":1,"d":2,"u":"Je op één taak richten laat het beter gaan.","uo":["Niet luier.","Klopt: je op één taak richten laat het beter gaan.","Onjuist.","Onjuist."],"uh":"Je op één taak richten laat het beter gaan."},{"v":"Wat is arbeidsproductiviteit?","o":["Het aantal werknemers","Het totale loon","De productie per werknemer","Het aantal machines"],"c":2,"d":2,"u":"De productie per werknemer per tijd.","uo":["Niet het aantal mensen.","Niet het loon.","Klopt: de productie per werknemer per tijd.","Niet het aantal machines."],"uh":"De productie per werknemer per tijd."},{"v":"Wie neemt mensen in dienst?","o":["De werkgever","De werknemer","De vakbond","De klant"],"c":0,"d":1,"u":"De werkgever neemt mensen aan.","uo":["Klopt: de werkgever neemt mensen aan.","De werknemer werkt in dienst.","De vakbond komt op voor werknemers.","De klant koopt."],"uh":"De werkgever neemt mensen aan."},{"v":"Wat staat er in een cao?","o":["De prijs van producten","De belastingtarieven","De koers van de euro","Afspraken over arbeidsvoorwaarden"],"c":3,"d":2,"u":"Afspraken over het werk voor een bedrijfstak.","uo":["Niet over productprijzen.","Niet over belasting.","Niet over de euro.","Klopt: afspraken over het werk voor een bedrijfstak."],"uh":"Afspraken over het werk voor een bedrijfstak."},{"v":"Wat is het minimumloon?","o":["Het hoogste loon","Het wettelijk laagste loon","Het gemiddelde loon","Het loon van de baas"],"c":1,"d":1,"u":"Het wettelijk laagste toegestane loon.","uo":["Juist niet het hoogste.","Klopt: het wettelijk laagste toegestane loon.","Niet het gemiddelde.","Niet specifiek de baas."],"uh":"Het wettelijk laagste toegestane loon."},{"v":"Wat doet een vakbond?","o":["Producten verkopen","Belasting innen","Opkomen voor werknemers","Geld uitlenen"],"c":2,"d":2,"u":"De vakbond komt op voor werknemers.","uo":["Nee, dat doet een winkel.","Dat doet de Belastingdienst.","Klopt: de vakbond komt op voor werknemers.","Dat doet een bank."],"uh":"De vakbond komt op voor werknemers."},{"v":"Wat is een werknemer?","o":["Iemand die in loondienst werkt","Iemand die personeel aanneemt","Een klant","Een fabriek"],"c":0,"d":1,"u":"Iemand die in loondienst werkt.","uo":["Klopt: iemand die in loondienst werkt.","Dat is de werkgever.","Een klant koopt.","Een fabriek maakt producten."],"uh":"Iemand die in loondienst werkt."},{"v":"Wat is een productiefactor?","o":["Een soort belasting","Een verzekering","Een klant","Een middel om te produceren"],"c":3,"d":3,"u":"Een middel om mee te produceren, zoals arbeid.","uo":["Geen belasting.","Geen verzekering.","Geen klant.","Klopt: een middel om mee te produceren, zoals arbeid."],"uh":"Een middel om mee te produceren, zoals arbeid."}],"begrippen":[{"t":"Brutoloon","d":"je loon vóór aftrek van belasting en premies"},{"t":"Nettoloon","d":"je loon na aftrek van belasting en premies"},{"t":"Loonheffing","d":"de belasting en premies die van je loon worden ingehouden"},{"t":"Arbeidsverdeling","d":"het opsplitsen van werk in aparte taken"},{"t":"Specialisatie","d":"je toeleggen op één taak of vak"},{"t":"Arbeidsproductiviteit","d":"de productie per werknemer per tijd"},{"t":"Werknemer","d":"iemand die in loondienst werkt"},{"t":"Werkgever","d":"iemand of een bedrijf dat mensen in dienst neemt"},{"t":"Cao","d":"afspraken over arbeidsvoorwaarden voor een hele bedrijfstak"},{"t":"Minimumloon","d":"het wettelijk laagste loon dat betaald mag worden"},{"t":"Vakbond","d":"een organisatie die opkomt voor werknemers"},{"t":"Productiefactor","d":"een middel om mee te produceren, zoals arbeid of kapitaal"}],"sam":"<div class=\"sam-intro\">Van je <strong>brutoloon</strong> gaan belasting en premies af; wat overblijft is je <strong>nettoloon</strong>. Door <strong>arbeidsverdeling</strong> en <strong>specialisatie</strong> stijgt de <strong>arbeidsproductiviteit</strong>.</div><div class=\"sam-head\">1. Van brutoloon naar nettoloon</div><p>Je <strong>brutoloon</strong> is je loon vóór aftrek. Daar gaat de <strong>loonheffing</strong> (belasting en premies) vanaf. Wat je op je rekening krijgt, is je <strong>nettoloon</strong>.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Je brutoloon is € 2.000 en de loonheffing is € 550. Hoeveel is je nettoloon?</div><ol class=\"sam-worked-steps\"><li>Nettoloon = brutoloon − loonheffing.</li><li>Nettoloon = 2.000 − 550.</li></ol><div class=\"sam-worked-ans\">✅ Je nettoloon is € 1.450.</div></div><div class=\"sam-head\">2. Productiever werken</div><p>Door <strong>arbeidsverdeling</strong> splits je het werk in aparte taken, en door <strong>specialisatie</strong> legt iemand zich toe op één taak. Daardoor stijgt de <strong>arbeidsproductiviteit</strong>: de productie per werknemer.</p><div class=\"sam-head\">3. Werkgevers, werknemers en afspraken</div><p>Een <strong>werkgever</strong> neemt mensen in dienst, een <strong>werknemer</strong> werkt in loondienst. In een <strong>cao</strong> staan de arbeidsvoorwaarden voor een hele bedrijfstak, mede bepaald door <strong>vakbonden</strong>. Het <strong>minimumloon</strong> is het wettelijk laagste loon.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Brutoloon</div><div class=\"sam-definitie-body\">je loon vóór aftrek van belasting en premies.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nettoloon</div><div class=\"sam-definitie-body\">je loon na aftrek van belasting en premies.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Loonheffing</div><div class=\"sam-definitie-body\">de belasting en premies die van je loon worden ingehouden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Arbeidsverdeling</div><div class=\"sam-definitie-body\">het opsplitsen van werk in aparte taken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Specialisatie</div><div class=\"sam-definitie-body\">je toeleggen op één taak of vak.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Arbeidsproductiviteit</div><div class=\"sam-definitie-body\">de productie per werknemer per tijd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werknemer</div><div class=\"sam-definitie-body\">iemand die in loondienst werkt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werkgever</div><div class=\"sam-definitie-body\">iemand of een bedrijf dat mensen in dienst neemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cao</div><div class=\"sam-definitie-body\">afspraken over arbeidsvoorwaarden voor een hele bedrijfstak.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Minimumloon</div><div class=\"sam-definitie-body\">het wettelijk laagste loon dat betaald mag worden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vakbond</div><div class=\"sam-definitie-body\">een organisatie die opkomt voor werknemers.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Productiefactor</div><div class=\"sam-definitie-body\">een middel om mee te produceren, zoals arbeid of kapitaal.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Brutoloon»</b> is loon vóór aftrek, terwijl <b>«Nettoloon»</b> loon na aftrek is. <b>«Loonheffing»</b> is inhoudingen op je loon, terwijl <b>«Brutoloon»</b> loon vóór aftrek is. <b>«Arbeidsverdeling»</b> is werk in taken opdelen, terwijl <b>«Specialisatie»</b> je op één taak richten is. <b>«Arbeidsproductiviteit»</b> is productie per werknemer, terwijl <b>«Arbeidsverdeling»</b> werk in taken opdelen is.</div>"},"D":{"sv":[{"v":"Wat is de omzet?","o":["De winst","Prijs maal aantal verkocht","De kosten","De belasting"],"c":1,"d":1,"u":"De totale verkoopopbrengst, prijs maal aantal.","uo":["Winst is omzet min kosten.","Klopt: de totale verkoopopbrengst, prijs maal aantal.","Kosten zijn iets anders.","Belasting is iets anders."],"uh":"De totale verkoopopbrengst, prijs maal aantal."},{"v":"Een winkel heeft € 5.000 omzet en € 3.500 kosten. Hoeveel winst?","o":["€ 8.500","€ 5.000","€ 1.500","€ 3.500"],"c":2,"d":3,"u":"5.000 − 3.500 = € 1.500.","uo":["Je moet aftrekken, niet optellen.","Dat is de omzet.","Klopt: 5.000 − 3.500 = € 1.500.","Dat zijn de kosten."],"uh":"5.000 − 3.500 = € 1.500."},{"v":"Wat zijn constante kosten?","o":["Kosten die gelijk blijven","Kosten die meebewegen","De totale omzet","De winst"],"c":0,"d":1,"u":"Ze veranderen niet met de productie.","uo":["Klopt: ze veranderen niet met de productie.","Dat zijn variabele kosten.","Omzet is iets anders.","Winst is iets anders."],"uh":"Ze veranderen niet met de productie."},{"v":"Wat zijn variabele kosten?","o":["Kosten die gelijk blijven","De vaste huur","De verzekering","Kosten die meebewegen met de productie"],"c":3,"d":3,"u":"Ze bewegen mee met de productie.","uo":["Dat zijn constante kosten.","Huur is meestal constant.","Verzekering is meestal constant.","Klopt: ze bewegen mee met de productie."],"uh":"Ze bewegen mee met de productie."},{"v":"Waarover betaal je btw?","o":["Over je spaargeld","Over de verkoopprijs","Over je loon","Over een lening"],"c":1,"d":2,"u":"Btw zit op de verkoopprijs.","uo":["Niet over sparen.","Klopt: btw zit op de verkoopprijs.","Over loon betaal je loonbelasting.","Niet over een lening."],"uh":"Btw zit op de verkoopprijs."},{"v":"Wat is winst?","o":["De totale omzet","Alle kosten samen","Omzet min kosten","De verkoopprijs"],"c":2,"d":1,"u":"Winst is omzet min kosten.","uo":["Dat is de omzet.","Dat zijn de kosten.","Klopt: winst is omzet min kosten.","De prijs van één product."],"uh":"Winst is omzet min kosten."},{"v":"Wat is de winstmarge?","o":["Verkoopprijs min inkoopprijs","De totale omzet","De belasting","De vaste huur"],"c":0,"d":2,"u":"Het verschil tussen verkoop- en inkoopprijs.","uo":["Klopt: het verschil tussen verkoop- en inkoopprijs.","Omzet is iets anders.","Belasting is iets anders.","Huur is een kostenpost."],"uh":"Het verschil tussen verkoop- en inkoopprijs."},{"v":"Wat betekent break-even?","o":["Veel winst maken","Verlies lijden","De hoogste omzet halen","Omzet gelijk aan de kosten"],"c":3,"d":3,"u":"De omzet is precies gelijk aan de kosten.","uo":["Nee, geen winst.","Nee, ook geen verlies.","Niet per se de hoogste.","Klopt: de omzet is precies gelijk aan de kosten."],"uh":"De omzet is precies gelijk aan de kosten."},{"v":"Wat is het verschil tussen verkoop- en inkoopprijs?","o":["De omzet","De winstmarge","De btw","De vaste huur"],"c":1,"d":2,"u":"Dat verschil is de winstmarge.","uo":["Omzet is prijs maal aantal.","Klopt: dat verschil is de winstmarge.","Btw is een belasting.","Huur is een kostenpost."],"uh":"Dat verschil is de winstmarge."},{"v":"Wat zijn kosten?","o":["De verkoopopbrengst","De gemaakte winst","Wat je uitgeeft om te produceren","Alleen de belasting"],"c":2,"d":2,"u":"Alles wat je uitgeeft om te produceren.","uo":["Dat is de omzet.","Winst is iets anders.","Klopt: alles wat je uitgeeft om te produceren.","Belasting is maar een deel."],"uh":"Alles wat je uitgeeft om te produceren."},{"v":"Wat is brutowinst?","o":["Omzet min inkoopwaarde","De totale kosten","De premie","Het nettoloon"],"c":0,"d":2,"u":"De omzet min de inkoopwaarde.","uo":["Klopt: de omzet min de inkoopwaarde.","Kosten zijn iets anders.","Premie hoort bij verzekeren.","Loon is iets anders."],"uh":"De omzet min de inkoopwaarde."},{"v":"Waarom betaalt een winkel btw af?","o":["Als extra spaargeld","Als winst voor de baas","Als loon voor personeel","Als belasting aan de overheid"],"c":3,"d":2,"u":"Btw draag je af aan de overheid.","uo":["Niet als spaargeld.","Btw is geen winst.","Btw is geen loon.","Klopt: btw draag je af aan de overheid."],"uh":"Btw draag je af aan de overheid."}],"begrippen":[{"t":"Omzet","d":"de totale verkoopopbrengst: prijs maal aantal"},{"t":"Verkoopprijs","d":"de prijs waarvoor je een product verkoopt"},{"t":"Inkoopprijs","d":"de prijs die je voor een product betaalt"},{"t":"Btw","d":"belasting die je over de verkoopprijs betaalt"},{"t":"Winst","d":"het bedrag dat overblijft na aftrek van de kosten"},{"t":"Kosten","d":"alles wat je uitgeeft om te produceren"},{"t":"Constante kosten","d":"kosten die niet veranderen met de productie"},{"t":"Variabele kosten","d":"kosten die meebewegen met de productie"},{"t":"Totale kosten","d":"de constante kosten plus de variabele kosten"},{"t":"Brutowinst","d":"de omzet min de inkoopwaarde van de verkochte producten"},{"t":"Winstmarge","d":"het verschil tussen verkoopprijs en inkoopprijs"},{"t":"Break-even","d":"het punt waarop de omzet precies gelijk is aan de kosten"}],"sam":"<div class=\"sam-intro\">De <strong>omzet</strong> is prijs maal aantal. Trek je de <strong>kosten</strong> ervan af, dan houd je <strong>winst</strong> over. Over de verkoopprijs betaal je <strong>btw</strong> aan de overheid.</div><div class=\"sam-head\">1. Omzet, kosten en winst</div><p>De <strong>omzet</strong> is de totale verkoopopbrengst: prijs maal aantal. De <strong>kosten</strong> is alles wat je uitgeeft om te produceren. De <strong>winst</strong> is wat overblijft als je de kosten van de omzet aftrekt.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Een bedrijf heeft een omzet van € 5.000 en kosten van € 3.500. Hoeveel winst maakt het?</div><ol class=\"sam-worked-steps\"><li>Winst = omzet − kosten.</li><li>Winst = 5.000 − 3.500.</li></ol><div class=\"sam-worked-ans\">✅ De winst is € 1.500.</div></div><div class=\"sam-head\">2. Constante en variabele kosten</div><p><strong>Constante kosten</strong> (zoals huur) veranderen niet met de productie; <strong>variabele kosten</strong> (zoals grondstoffen) bewegen wél mee. Samen vormen ze de <strong>totale kosten</strong>. Bij het <strong>break-even</strong>punt is de omzet precies gelijk aan de kosten: geen winst, geen verlies.</p><div class=\"sam-head\">3. Prijzen en btw</div><p>Het verschil tussen <strong>verkoopprijs</strong> en <strong>inkoopprijs</strong> is de <strong>winstmarge</strong>. Over de verkoopprijs reken je <strong>btw</strong>, die je afdraagt aan de overheid.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Omzet</div><div class=\"sam-definitie-body\">de totale verkoopopbrengst: prijs maal aantal.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verkoopprijs</div><div class=\"sam-definitie-body\">de prijs waarvoor je een product verkoopt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkoopprijs</div><div class=\"sam-definitie-body\">de prijs die je voor een product betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Btw</div><div class=\"sam-definitie-body\">belasting die je over de verkoopprijs betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Winst</div><div class=\"sam-definitie-body\">het bedrag dat overblijft na aftrek van de kosten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kosten</div><div class=\"sam-definitie-body\">alles wat je uitgeeft om te produceren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Constante kosten</div><div class=\"sam-definitie-body\">kosten die niet veranderen met de productie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Variabele kosten</div><div class=\"sam-definitie-body\">kosten die meebewegen met de productie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Totale kosten</div><div class=\"sam-definitie-body\">de constante kosten plus de variabele kosten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Brutowinst</div><div class=\"sam-definitie-body\">de omzet min de inkoopwaarde van de verkochte producten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Winstmarge</div><div class=\"sam-definitie-body\">het verschil tussen verkoopprijs en inkoopprijs.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Break-even</div><div class=\"sam-definitie-body\">het punt waarop de omzet precies gelijk is aan de kosten.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Omzet»</b> is prijs maal aantal, terwijl <b>«Winst»</b> opbrengst min kosten is. <b>«Verkoopprijs»</b> is prijs bij verkoop, terwijl <b>«Inkoopprijs»</b> prijs bij inkoop is. <b>«Kosten»</b> is uitgaven om te produceren, terwijl <b>«Omzet»</b> prijs maal aantal is. <b>«Constante kosten»</b> is blijven gelijk, terwijl <b>«Variabele kosten»</b> bewegen mee is.</div>"},"E":{"sv":[{"v":"Waarom heft de overheid belasting?","o":["Om winst te maken","Om collectieve voorzieningen te betalen","Om te sparen","Om te lenen"],"c":1,"d":2,"u":"Om wegen, onderwijs en veiligheid te betalen.","uo":["De overheid maakt geen winst.","Klopt: om wegen, onderwijs en veiligheid te betalen.","Niet om te sparen.","Niet om te lenen."],"uh":"Om wegen, onderwijs en veiligheid te betalen."},{"v":"Wat is een directe belasting?","o":["Btw op producten","Accijns op benzine","Belasting op inkomen","Een keurmerk"],"c":2,"d":2,"u":"Directe belasting gaat over inkomen of winst.","uo":["Btw is indirect.","Accijns is indirect.","Klopt: directe belasting gaat over inkomen of winst.","Een keurmerk is geen belasting."],"uh":"Directe belasting gaat over inkomen of winst."},{"v":"Wat is een indirecte belasting?","o":["Belasting in de prijs (btw)","Belasting op je inkomen","Een subsidie","Een uitkering"],"c":0,"d":2,"u":"Die zit in de prijs, zoals btw.","uo":["Klopt: die zit in de prijs, zoals btw.","Dat is directe belasting.","Een subsidie is geen belasting.","Een uitkering is geen belasting."],"uh":"Die zit in de prijs, zoals btw."},{"v":"Wat is een collectieve voorziening?","o":["Iets voor jou alleen","Een verzekering","Een lening","Iets dat de overheid voor iedereen regelt"],"c":3,"d":2,"u":"Iets dat de overheid voor iedereen regelt, zoals wegen.","uo":["Nee, juist voor iedereen.","Geen verzekering.","Geen lening.","Klopt: iets dat de overheid voor iedereen regelt, zoals wegen."],"uh":"Iets dat de overheid voor iedereen regelt, zoals wegen."},{"v":"Wat is accijns?","o":["Belasting op inkomen","Extra belasting op bv. benzine","Een subsidie","Een uitkering"],"c":1,"d":2,"u":"Extra belasting op producten zoals alcohol en benzine.","uo":["Dat is inkomstenbelasting.","Klopt: extra belasting op producten zoals alcohol en benzine.","Geen subsidie.","Geen uitkering."],"uh":"Extra belasting op producten zoals alcohol en benzine."},{"v":"Wat is een subsidie?","o":["Een belasting","Een boete","Geld om iets te stimuleren","Een lening"],"c":2,"d":1,"u":"Geld van de overheid om iets te stimuleren.","uo":["Geen belasting.","Geen boete.","Klopt: geld van de overheid om iets te stimuleren.","Geen lening."],"uh":"Geld van de overheid om iets te stimuleren."},{"v":"Wat is een uitkering?","o":["Geld bij te weinig inkomen","Een belasting","Een keurmerk","Een verzekeringspremie"],"c":0,"d":1,"u":"Geld van de overheid voor wie te weinig inkomen heeft.","uo":["Klopt: geld van de overheid voor wie te weinig inkomen heeft.","Geen belasting.","Geen keurmerk.","Een premie is iets anders."],"uh":"Geld van de overheid voor wie te weinig inkomen heeft."},{"v":"Wat staat er in de begroting van de overheid?","o":["De koers van de euro","De prijzen in de winkel","De rente bij de bank","Verwachte inkomsten en uitgaven"],"c":3,"d":2,"u":"De verwachte inkomsten en uitgaven.","uo":["Niet de euro.","Niet winkelprijzen.","Niet de rente.","Klopt: de verwachte inkomsten en uitgaven."],"uh":"De verwachte inkomsten en uitgaven."},{"v":"Wat is de staatsschuld?","o":["Het spaargeld van de overheid","Wat de overheid heeft geleend","De totale belasting","De begroting"],"c":1,"d":2,"u":"Het totale bedrag dat de overheid heeft geleend.","uo":["Nee, juist schuld.","Klopt: het totale bedrag dat de overheid heeft geleend.","Niet de belasting.","De begroting is een plan."],"uh":"Het totale bedrag dat de overheid heeft geleend."},{"v":"Wat hoort bij infrastructuur?","o":["Spaargeld","Belasting","Wegen en bruggen","Verzekeringen"],"c":2,"d":1,"u":"Voorzieningen zoals wegen, bruggen en spoor.","uo":["Nee, dat klopt niet.","Nee, dat klopt niet.","Klopt: voorzieningen zoals wegen, bruggen en spoor.","Nee, dat klopt niet."],"uh":"Voorzieningen zoals wegen, bruggen en spoor."},{"v":"Wat is een overheidstaak?","o":["Een taak voor de samenleving","Een taak van een bedrijf","Sparen bij een bank","Iets kopen in de winkel"],"c":0,"d":1,"u":"Een taak die de overheid voor de samenleving doet.","uo":["Klopt: een taak die de overheid voor de samenleving doet.","Dat doet een bedrijf.","Dat is iets anders.","Dat is iets anders."],"uh":"Een taak die de overheid voor de samenleving doet."},{"v":"Wat is het verschil tussen subsidie en uitkering?","o":["Beide zijn een belasting","Beide zijn een lening","Er is geen verschil","Subsidie stimuleert, uitkering helpt bij te weinig inkomen"],"c":3,"d":3,"u":"Subsidie stimuleert iets, een uitkering helpt bij te weinig inkomen.","uo":["Het is geen belasting.","Het is geen lening.","Er is wel verschil.","Klopt: subsidie stimuleert iets, een uitkering helpt bij te weinig inkomen."],"uh":"Subsidie stimuleert iets, een uitkering helpt bij te weinig inkomen."}],"begrippen":[{"t":"Belasting","d":"een verplichte betaling aan de overheid"},{"t":"Directe belasting","d":"belasting op inkomen of winst"},{"t":"Indirecte belasting","d":"belasting die in de prijs van producten zit"},{"t":"Inkomstenbelasting","d":"belasting die je over je inkomen betaalt"},{"t":"Accijns","d":"extra belasting op producten zoals alcohol en benzine"},{"t":"Collectieve voorziening","d":"iets dat de overheid voor iedereen regelt, zoals wegen"},{"t":"Subsidie","d":"een bijdrage van de overheid om iets te stimuleren"},{"t":"Uitkering","d":"geld van de overheid voor wie niet genoeg inkomen heeft"},{"t":"Begroting","d":"het overzicht van verwachte inkomsten en uitgaven van de overheid"},{"t":"Staatsschuld","d":"het totale bedrag dat de overheid heeft geleend"},{"t":"Infrastructuur","d":"voorzieningen zoals wegen, bruggen en spoor"},{"t":"Overheidstaak","d":"een taak die de overheid voor de samenleving uitvoert"}],"sam":"<div class=\"sam-intro\">De <strong>overheid</strong> heft <strong>belasting</strong> om <strong>collectieve voorzieningen</strong> zoals wegen en onderwijs te betalen. <strong>Directe belasting</strong> gaat over inkomen, <strong>indirecte belasting</strong> zit in de prijs.</div><div class=\"sam-head\">1. Waarom belasting?</div><p>De overheid betaalt <strong>collectieve voorzieningen</strong> die er voor iedereen zijn, zoals <strong>infrastructuur</strong>, onderwijs en veiligheid. Dat geld komt binnen via <strong>belasting</strong>: een verplichte betaling aan de staat. Zulke taken heten <strong>overheidstaken</strong>.</p><div class=\"sam-head\">2. Directe en indirecte belasting</div><p>Een <strong>directe belasting</strong> gaat over je inkomen of winst, zoals de <strong>inkomstenbelasting</strong>. Een <strong>indirecte belasting</strong> zit verwerkt in de prijs van producten, zoals de <strong>btw</strong>. Op sommige producten zit extra belasting, de <strong>accijns</strong>.</p><div class=\"sam-head\">3. De begroting</div><p>In de <strong>begroting</strong> zet de overheid de verwachte inkomsten en uitgaven op een rij. Geeft de overheid meer uit dan er binnenkomt, dan groeit de <strong>staatsschuld</strong>. Met een <strong>subsidie</strong> stimuleert de overheid iets; met een <strong>uitkering</strong> helpt ze wie te weinig inkomen heeft.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Belasting</div><div class=\"sam-definitie-body\">een verplichte betaling aan de overheid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Directe belasting</div><div class=\"sam-definitie-body\">belasting op inkomen of winst.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Indirecte belasting</div><div class=\"sam-definitie-body\">belasting die in de prijs van producten zit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkomstenbelasting</div><div class=\"sam-definitie-body\">belasting die je over je inkomen betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Accijns</div><div class=\"sam-definitie-body\">extra belasting op producten zoals alcohol en benzine.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Collectieve voorziening</div><div class=\"sam-definitie-body\">iets dat de overheid voor iedereen regelt, zoals wegen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Subsidie</div><div class=\"sam-definitie-body\">een bijdrage van de overheid om iets te stimuleren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitkering</div><div class=\"sam-definitie-body\">geld van de overheid voor wie niet genoeg inkomen heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Begroting</div><div class=\"sam-definitie-body\">het overzicht van verwachte inkomsten en uitgaven van de overheid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Staatsschuld</div><div class=\"sam-definitie-body\">het totale bedrag dat de overheid heeft geleend.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Infrastructuur</div><div class=\"sam-definitie-body\">voorzieningen zoals wegen, bruggen en spoor.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Overheidstaak</div><div class=\"sam-definitie-body\">een taak die de overheid voor de samenleving uitvoert.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Belasting»</b> is verplichte betaling aan de staat, terwijl <b>«Accijns»</b> extra belasting op producten is. <b>«Directe belasting»</b> is belasting op inkomen, terwijl <b>«Indirecte belasting»</b> belasting in de prijs is. <b>«Inkomstenbelasting»</b> is belasting over inkomen, terwijl <b>«Directe belasting»</b> belasting op inkomen is. <b>«Collectieve voorziening»</b> is voor iedereen geregeld, terwijl <b>«Subsidie»</b> geld om te stimuleren is.</div>"},"F":{"sv":[{"v":"Wat is import?","o":["Uitvoer naar buitenland","Invoer uit het buitenland","Belasting op producten","Sparen in het buitenland"],"c":1,"d":1,"u":"Invoer van goederen uit het buitenland.","uo":["Dat is export.","Klopt: invoer van goederen uit het buitenland.","Dat is iets anders.","Dat is iets anders."],"uh":"Invoer van goederen uit het buitenland."},{"v":"Wat is export?","o":["Invoer uit het buitenland","Een belasting","Uitvoer naar het buitenland","Een lening"],"c":2,"d":1,"u":"Uitvoer van goederen naar het buitenland.","uo":["Dat is import.","Geen belasting.","Klopt: uitvoer van goederen naar het buitenland.","Geen lening."],"uh":"Uitvoer van goederen naar het buitenland."},{"v":"Wat is een wisselkoers?","o":["De prijs van een munt in een andere","De rente op sparen","Een belasting","Een keurmerk"],"c":0,"d":2,"u":"De prijs van de ene munt in de andere.","uo":["Klopt: de prijs van de ene munt in de andere.","Rente is iets anders.","Geen belasting.","Geen keurmerk."],"uh":"De prijs van de ene munt in de andere."},{"v":"Wat is de euro?","o":["Een belasting","Een bank","Een wisselkoers","De munt van veel EU-landen"],"c":3,"d":1,"u":"De gezamenlijke munt van veel EU-landen.","uo":["Geen belasting.","Geen bank.","Een koers is iets anders.","Klopt: de gezamenlijke munt van veel EU-landen."],"uh":"De gezamenlijke munt van veel EU-landen."},{"v":"Wat is de Europese Unie?","o":["Een bedrijf","Een samenwerking van Europese landen","Een munt","Een belasting"],"c":1,"d":1,"u":"Een samenwerkingsverband van Europese landen.","uo":["Geen bedrijf.","Klopt: een samenwerkingsverband van Europese landen.","De munt is de euro.","Geen belasting."],"uh":"Een samenwerkingsverband van Europese landen."},{"v":"Wat is vrijhandel?","o":["Handel met veel drempels","Handel verbieden","Handel zonder belemmeringen","Alleen binnenlandse handel"],"c":2,"d":2,"u":"Handel zonder belemmeringen tussen landen.","uo":["Nee, juist zonder drempels.","Nee, dat klopt niet.","Klopt: handel zonder belemmeringen tussen landen.","Nee, ook met het buitenland."],"uh":"Handel zonder belemmeringen tussen landen."},{"v":"Wat is protectionisme?","o":["De eigen markt beschermen","Vrij handelen","Meer importeren","Grenzen openstellen"],"c":0,"d":2,"u":"Eigen bedrijven beschermen tegen buitenlandse concurrentie.","uo":["Klopt: eigen bedrijven beschermen tegen buitenlandse concurrentie.","Dat is vrijhandel.","Onjuist.","Onjuist."],"uh":"Eigen bedrijven beschermen tegen buitenlandse concurrentie."},{"v":"Wat is de handelsbalans?","o":["Het spaargeld","De begroting","De wisselkoers","Het verschil tussen export en import"],"c":3,"d":3,"u":"Het verschil tussen export en import.","uo":["Nee, dat klopt niet.","De begroting is iets anders.","Een koers is iets anders.","Klopt: het verschil tussen export en import."],"uh":"Het verschil tussen export en import."},{"v":"Wat is globalisering?","o":["Landen sluiten zich af","Landen raken wereldwijd verweven","Alleen binnenlandse handel","Minder handel"],"c":1,"d":2,"u":"Landen raken wereldwijd steeds meer verweven.","uo":["Juist het tegenovergestelde.","Klopt: landen raken wereldwijd steeds meer verweven.","Nee, dat klopt niet.","Nee, dat klopt niet."],"uh":"Landen raken wereldwijd steeds meer verweven."},{"v":"Wat is ontwikkelingssamenwerking?","o":["Handel met winst","Belasting innen","Hulp aan armere landen","Een lening bij de bank"],"c":2,"d":2,"u":"Hulp aan armere landen om zich te ontwikkelen.","uo":["Niet gericht op winst.","Geen belasting.","Klopt: hulp aan armere landen om zich te ontwikkelen.","Geen lening."],"uh":"Hulp aan armere landen om zich te ontwikkelen."},{"v":"Wat zijn invoerrechten?","o":["Belasting op ingevoerde goederen","Belasting op je loon","Een subsidie","Een keurmerk"],"c":0,"d":2,"u":"Belasting op goederen die je invoert.","uo":["Klopt: belasting op goederen die je invoert.","Dat is loonbelasting.","Geen subsidie.","Geen keurmerk."],"uh":"Belasting op goederen die je invoert."},{"v":"Wat is een voordeel van de interne markt van de EU?","o":["Meer grenzen","Meer invoerrechten","Hogere belasting","Vrije handel zonder grenzen"],"c":3,"d":3,"u":"Vrije handel binnen de EU zonder grenzen.","uo":["Juist minder grenzen.","Juist minder rechten.","Niet per se.","Klopt: vrije handel binnen de EU zonder grenzen."],"uh":"Vrije handel binnen de EU zonder grenzen."}],"begrippen":[{"t":"Import","d":"het invoeren van goederen uit het buitenland"},{"t":"Export","d":"het uitvoeren van goederen naar het buitenland"},{"t":"Handelsbalans","d":"het verschil tussen de export en de import"},{"t":"Wisselkoers","d":"de prijs van de ene munt uitgedrukt in de andere"},{"t":"Euro","d":"de gezamenlijke munt van veel EU-landen"},{"t":"Europese Unie","d":"een samenwerkingsverband van Europese landen"},{"t":"Interne markt","d":"de vrije handel binnen de EU zonder grenzen"},{"t":"Invoerrechten","d":"belasting op goederen die worden ingevoerd"},{"t":"Ontwikkelingssamenwerking","d":"hulp aan armere landen om zich te ontwikkelen"},{"t":"Vrijhandel","d":"handel zonder belemmeringen tussen landen"},{"t":"Protectionisme","d":"eigen bedrijven beschermen tegen buitenlandse concurrentie"},{"t":"Globalisering","d":"het steeds meer verweven raken van landen wereldwijd"}],"sam":"<div class=\"sam-intro\">Landen handelen met elkaar: <strong>import</strong> is invoer, <strong>export</strong> is uitvoer. Voor handel met andere munten geldt een <strong>wisselkoers</strong>. Binnen de <strong>Europese Unie</strong> is er vrije handel.</div><div class=\"sam-head\">1. Import en export</div><p><strong>Import</strong> is het invoeren van goederen uit het buitenland, <strong>export</strong> het uitvoeren ervan. Het verschil tussen export en import heet de <strong>handelsbalans</strong>.</p><div class=\"sam-head\">2. Geld over de grens</div><p>Handel je met een land met een andere munt, dan speelt de <strong>wisselkoers</strong>: de prijs van de ene munt in de andere. Veel EU-landen gebruiken dezelfde munt, de <strong>euro</strong>, zodat wisselen niet meer nodig is. Soms heft een land <strong>invoerrechten</strong> op buitenlandse goederen.</p><div class=\"sam-head\">3. Samenwerking en globalisering</div><p>De <strong>Europese Unie</strong> vormt één <strong>interne markt</strong> met vrije handel. Landen kiezen tussen <strong>vrijhandel</strong> (geen drempels) en <strong>protectionisme</strong> (eigen markt beschermen). Door <strong>globalisering</strong> raken landen wereldwijd verweven; met <strong>ontwikkelingssamenwerking</strong> worden armere landen geholpen.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Import</div><div class=\"sam-definitie-body\">het invoeren van goederen uit het buitenland.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Export</div><div class=\"sam-definitie-body\">het uitvoeren van goederen naar het buitenland.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Handelsbalans</div><div class=\"sam-definitie-body\">het verschil tussen de export en de import.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wisselkoers</div><div class=\"sam-definitie-body\">de prijs van de ene munt uitgedrukt in de andere.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Euro</div><div class=\"sam-definitie-body\">de gezamenlijke munt van veel EU-landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Europese Unie</div><div class=\"sam-definitie-body\">een samenwerkingsverband van Europese landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Interne markt</div><div class=\"sam-definitie-body\">de vrije handel binnen de EU zonder grenzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Invoerrechten</div><div class=\"sam-definitie-body\">belasting op goederen die worden ingevoerd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontwikkelingssamenwerking</div><div class=\"sam-definitie-body\">hulp aan armere landen om zich te ontwikkelen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vrijhandel</div><div class=\"sam-definitie-body\">handel zonder belemmeringen tussen landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Protectionisme</div><div class=\"sam-definitie-body\">eigen bedrijven beschermen tegen buitenlandse concurrentie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Globalisering</div><div class=\"sam-definitie-body\">het steeds meer verweven raken van landen wereldwijd.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Import»</b> is invoer uit buitenland, terwijl <b>«Export»</b> uitvoer naar buitenland is. <b>«Handelsbalans»</b> is export min import, terwijl <b>«Wisselkoers»</b> prijs van een munt is. <b>«Wisselkoers»</b> is prijs van een munt, terwijl <b>«Euro»</b> de munt van de eurozone is. <b>«Europese Unie»</b> is samenwerkende EU-landen, terwijl <b>«Interne markt»</b> vrije handel in de EU is.</div>"},"G":{"sv":[{"v":"Wat zijn milieukosten?","o":["De prijs van een product","De kosten van schade aan het milieu","De winst","De belasting"],"c":1,"d":2,"u":"De kosten van milieuschade.","uo":["Niet de productprijs.","Klopt: de kosten van milieuschade.","Winst is iets anders.","Belasting is iets anders."],"uh":"De kosten van milieuschade."},{"v":"Wat zijn externe kosten?","o":["Kosten die de maker betaalt","De gemaakte winst","Kosten die de samenleving draagt","De inkoopprijs"],"c":2,"d":2,"u":"Kosten die de samenleving draagt, niet de vervuiler.","uo":["Nee, juist niet de maker.","Winst is iets anders.","Klopt: kosten die de samenleving draagt, niet de vervuiler.","Iets anders."],"uh":"Kosten die de samenleving draagt, niet de vervuiler."},{"v":"Wat betekent het vervuiler-betaalt-principe?","o":["Wie vervuilt, betaalt","De overheid betaalt alles","Niemand betaalt","De klant betaalt nooit"],"c":0,"d":2,"u":"Wie vervuilt betaalt zelf de kosten.","uo":["Klopt: wie vervuilt betaalt zelf de kosten.","Nee, dat klopt niet.","Nee, dat klopt niet.","Nee, dat klopt niet."],"uh":"Wie vervuilt betaalt zelf de kosten."},{"v":"Wat is een circulaire economie?","o":["Alles wordt weggegooid","Meer verbranden","Grondstoffen uitputten","Grondstoffen worden hergebruikt"],"c":3,"d":3,"u":"Een economie waarin grondstoffen worden hergebruikt.","uo":["Juist niet.","Nee, dat klopt niet.","Nee, dat klopt niet.","Klopt: een economie waarin grondstoffen worden hergebruikt."],"uh":"Een economie waarin grondstoffen worden hergebruikt."},{"v":"Wat gebeurt er bij recycling?","o":["Afval blijft liggen","Afval wordt nieuwe grondstof","Afval verdwijnt","Afval wordt duurder"],"c":1,"d":1,"u":"Afval wordt tot nieuwe grondstof verwerkt.","uo":["Nee, dat klopt niet.","Klopt: afval wordt tot nieuwe grondstof verwerkt.","Nee, dat klopt niet.","Niet per se."],"uh":"Afval wordt tot nieuwe grondstof verwerkt."},{"v":"Wat is uitputting van grondstoffen?","o":["Meer grondstoffen krijgen","Grondstoffen hergebruiken","Grondstoffen raken op","Grondstoffen sparen"],"c":2,"d":2,"u":"Grondstoffen raken op.","uo":["Nee, dat klopt niet.","Dat is juist goed.","Klopt: grondstoffen raken op.","Nee, dat klopt niet."],"uh":"Grondstoffen raken op."},{"v":"Wat is duurzaam produceren?","o":["Produceren met zorg voor milieu","Zoveel mogelijk vervuilen","Alles wegwerpen","Grondstoffen uitputten"],"c":0,"d":1,"u":"Produceren met zorg voor mens en milieu.","uo":["Klopt: produceren met zorg voor mens en milieu.","Nee, dat klopt niet.","Nee, dat klopt niet.","Nee, dat klopt niet."],"uh":"Produceren met zorg voor mens en milieu."},{"v":"Wat is een fossiele brandstof?","o":["Zonne-energie","Windenergie","Waterkracht","Aardolie"],"c":3,"d":1,"u":"Aardolie is fossiel en raakt op.","uo":["Duurzaam.","Duurzaam.","Duurzaam.","Klopt: aardolie is fossiel en raakt op."],"uh":"Aardolie is fossiel en raakt op."},{"v":"Waarom zijn externe kosten een probleem?","o":["De maker betaalt te veel","De samenleving draait ervoor op","Er is geen probleem","Producten worden gratis"],"c":1,"d":3,"u":"De samenleving betaalt de schade, niet de vervuiler.","uo":["Juist niet de maker.","Klopt: de samenleving betaalt de schade, niet de vervuiler.","Er is wel een probleem.","Nee, dat klopt niet."],"uh":"De samenleving betaalt de schade, niet de vervuiler."},{"v":"Wat is duurzame ontwikkeling?","o":["Snelle uitputting","Alleen nu belangrijk","Groei die de toekomst niet schaadt","Meer vervuiling"],"c":2,"d":2,"u":"Ontwikkeling die de toekomst niet schaadt.","uo":["Nee, dat klopt niet.","Nee, ook de toekomst telt.","Klopt: ontwikkeling die de toekomst niet schaadt.","Nee, dat klopt niet."],"uh":"Ontwikkeling die de toekomst niet schaadt."},{"v":"Wat is groene energie?","o":["Energie die niet opraakt","Aardgas","Steenkool","Aardolie"],"c":0,"d":1,"u":"Uit bronnen die niet opraken, zoals zon en wind.","uo":["Klopt: uit bronnen die niet opraken, zoals zon en wind.","Fossiel.","Fossiel.","Fossiel."],"uh":"Uit bronnen die niet opraken, zoals zon en wind."},{"v":"Wat is consuminderen?","o":["Meer kopen","Alles vervangen","Vaker weggooien","Bewust minder gebruiken"],"c":3,"d":2,"u":"Bewust minder kopen en gebruiken.","uo":["Juist niet.","Nee, dat klopt niet.","Nee, dat klopt niet.","Klopt: bewust minder kopen en gebruiken."],"uh":"Bewust minder kopen en gebruiken."}],"begrippen":[{"t":"Milieukosten","d":"de kosten van schade aan het milieu"},{"t":"Externe kosten","d":"kosten die niet de veroorzaker maar de samenleving draagt"},{"t":"Vervuiler-betaalt-principe","d":"wie vervuilt, betaalt zelf de kosten daarvan"},{"t":"Duurzaam produceren","d":"produceren met zorg voor mens en milieu"},{"t":"Circulaire economie","d":"een economie waarin grondstoffen worden hergebruikt"},{"t":"Recycling","d":"afval verwerken tot nieuwe grondstoffen"},{"t":"Grondstof","d":"een natuurlijke stof waarvan je iets maakt"},{"t":"Uitputting","d":"het opraken van grondstoffen"},{"t":"Duurzame ontwikkeling","d":"ontwikkeling die de toekomst niet schaadt"},{"t":"Fossiele brandstof","d":"brandstof uit resten van organismen, zoals olie en gas"},{"t":"Groene energie","d":"energie uit bronnen die niet opraken"},{"t":"Consuminderen","d":"bewust minder kopen en gebruiken"}],"sam":"<div class=\"sam-intro\">Produceren kost niet alleen geld maar ook <strong>milieukosten</strong>. Bij <strong>externe kosten</strong> draait de samenleving op voor de schade. <strong>Duurzaam produceren</strong> en een <strong>circulaire economie</strong> beperken de <strong>uitputting</strong> van grondstoffen.</div><div class=\"sam-head\">1. De kosten van vervuiling</div><p>Vervuiling brengt <strong>milieukosten</strong> met zich mee. Vaak zijn dat <strong>externe kosten</strong>: niet de vervuiler maar de samenleving betaalt. Met het <strong>vervuiler-betaalt-principe</strong> legt de overheid die kosten juist bij de veroorzaker.</p><div class=\"sam-head\">2. Duurzaam en circulair</div><p><strong>Duurzaam produceren</strong> houdt rekening met mens en milieu. In een <strong>circulaire economie</strong> worden grondstoffen steeds hergebruikt via <strong>recycling</strong>, zodat de <strong>uitputting</strong> van grondstoffen afneemt. Dat past bij <strong>duurzame ontwikkeling</strong>: groei die de toekomst niet schaadt.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Milieukosten</div><div class=\"sam-definitie-body\">de kosten van schade aan het milieu.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Externe kosten</div><div class=\"sam-definitie-body\">kosten die niet de veroorzaker maar de samenleving draagt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vervuiler-betaalt-principe</div><div class=\"sam-definitie-body\">wie vervuilt, betaalt zelf de kosten daarvan.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Duurzaam produceren</div><div class=\"sam-definitie-body\">produceren met zorg voor mens en milieu.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Circulaire economie</div><div class=\"sam-definitie-body\">een economie waarin grondstoffen worden hergebruikt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recycling</div><div class=\"sam-definitie-body\">afval verwerken tot nieuwe grondstoffen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondstof</div><div class=\"sam-definitie-body\">een natuurlijke stof waarvan je iets maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitputting</div><div class=\"sam-definitie-body\">het opraken van grondstoffen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Duurzame ontwikkeling</div><div class=\"sam-definitie-body\">ontwikkeling die de toekomst niet schaadt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fossiele brandstof</div><div class=\"sam-definitie-body\">brandstof uit resten van organismen, zoals olie en gas.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Groene energie</div><div class=\"sam-definitie-body\">energie uit bronnen die niet opraken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consuminderen</div><div class=\"sam-definitie-body\">bewust minder kopen en gebruiken.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Milieukosten»</b> is kosten van milieuschade, terwijl <b>«Externe kosten»</b> samenleving betaalt de schade is. <b>«Vervuiler-betaalt-principe»</b> is vervuiler betaalt, terwijl <b>«Externe kosten»</b> samenleving betaalt de schade is. <b>«Duurzaam produceren»</b> is produceren met zorg, terwijl <b>«Circulaire economie»</b> grondstoffen hergebruiken is. <b>«Circulaire economie»</b> is grondstoffen hergebruiken, terwijl <b>«Recycling»</b> afval hergebruiken is.</div>"},"H":{"sv":[{"v":"Wat is rente?","o":["Een belasting","De vergoeding voor geld lenen of uitlenen","Je spaargeld","Een boete"],"c":1,"d":1,"u":"De vergoeding voor het gebruik van geld.","uo":["Geen belasting.","Klopt: de vergoeding voor het gebruik van geld.","Sparen is iets anders.","Geen boete."],"uh":"De vergoeding voor het gebruik van geld."},{"v":"Wat is samengestelde interest?","o":["Rente over alleen het startbedrag","Helemaal geen rente","Rente ook over eerdere rente","Een belasting"],"c":2,"d":2,"u":"Je krijgt rente over de rente.","uo":["Dat is enkelvoudige interest.","Nee, dat klopt niet.","Klopt: je krijgt rente over de rente.","Geen belasting."],"uh":"Je krijgt rente over de rente."},{"v":"Wat is enkelvoudige interest?","o":["Rente over alleen het startbedrag","Rente over rente","Helemaal geen rente","Een lening"],"c":0,"d":2,"u":"Rente alleen over het oorspronkelijke bedrag.","uo":["Klopt: rente alleen over het oorspronkelijke bedrag.","Dat is samengesteld.","Nee, dat klopt niet.","Een lening is iets anders."],"uh":"Rente alleen over het oorspronkelijke bedrag."},{"v":"Je zet € 100 weg tegen 10% rente. Hoeveel rente in jaar 2 (samengesteld)?","o":["€ 10","€ 0","€ 100","€ 11"],"c":3,"d":3,"u":"10% over € 110 is € 11.","uo":["Dat is jaar 1.","Er is wel rente.","Veel te veel.","Klopt: 10% over € 110 is € 11."],"uh":"10% over € 110 is € 11."},{"v":"Wat is een hypotheek?","o":["Een spaarrekening","Een lening voor een huis","Een belasting","Een verzekering"],"c":1,"d":1,"u":"Een lening voor een huis, met het huis als onderpand.","uo":["Nee, dat klopt niet.","Klopt: een lening voor een huis, met het huis als onderpand.","Geen belasting.","Geen verzekering."],"uh":"Een lening voor een huis, met het huis als onderpand."},{"v":"Wat is onderpand?","o":["Je spaargeld","De rente","Bezit dat de bank mag verkopen bij niet-betalen","De premie"],"c":2,"d":2,"u":"Zekerheid voor de bank.","uo":["Nee, dat klopt niet.","Rente is iets anders.","Klopt: zekerheid voor de bank.","Premie hoort bij verzekeren."],"uh":"Zekerheid voor de bank."},{"v":"Wat is aflossing?","o":["Het terugbetalen van een lening","De rente","Het sparen","De premie"],"c":0,"d":1,"u":"Het terugbetalen van een lening.","uo":["Klopt: het terugbetalen van een lening.","Rente is de vergoeding.","Sparen is iets anders.","Premie is iets anders."],"uh":"Het terugbetalen van een lening."},{"v":"Wat doet de centrale bank?","o":["Producten verkopen","Belasting innen","Loon betalen","Het geld bewaken"],"c":3,"d":2,"u":"De centrale bank bewaakt de waarde van het geld.","uo":["Nee, dat klopt niet.","Dat doet de Belastingdienst.","Nee, dat klopt niet.","Klopt: de centrale bank bewaakt de waarde van het geld."],"uh":"De centrale bank bewaakt de waarde van het geld."},{"v":"Wat is krediet?","o":["Een belasting","De mogelijkheid om te lenen","Je spaargeld","Een keurmerk"],"c":1,"d":2,"u":"De mogelijkheid om geld te lenen.","uo":["Geen belasting.","Klopt: de mogelijkheid om geld te lenen.","Sparen is iets anders.","Geen keurmerk."],"uh":"De mogelijkheid om geld te lenen."},{"v":"Wat gebeurt er bij inflatie met je geld?","o":["Het wordt meer waard","Het blijft gelijk","Het wordt minder waard","Het verdwijnt"],"c":2,"d":2,"u":"Door stijgende prijzen wordt geld minder waard.","uo":["Nee, minder.","Nee, dat klopt niet.","Klopt: door stijgende prijzen wordt geld minder waard.","Geld verdwijnt niet."],"uh":"Door stijgende prijzen wordt geld minder waard."},{"v":"Wat is sparen?","o":["Geld opzijzetten bij een bank","Geld lenen","Geld uitgeven","Belasting betalen"],"c":0,"d":1,"u":"Geld opzijzetten, vaak tegen rente.","uo":["Klopt: geld opzijzetten, vaak tegen rente.","Dat is het tegenovergestelde.","Uitgeven is iets anders.","Belasting is iets anders."],"uh":"Geld opzijzetten, vaak tegen rente."},{"v":"Waarom groeit spaargeld sneller met samengestelde interest?","o":["Omdat de bank meer geeft","Omdat je meer stort","Omdat de rente daalt","Omdat je rente over rente krijgt"],"c":3,"d":3,"u":"Je krijgt ook rente over de eerder ontvangen rente.","uo":["Niet zomaar.","Niet per se.","Nee, dat klopt niet.","Klopt: je krijgt ook rente over de eerder ontvangen rente."],"uh":"Je krijgt ook rente over de eerder ontvangen rente."}],"begrippen":[{"t":"Rente","d":"de vergoeding voor het lenen of uitlenen van geld"},{"t":"Samengestelde interest","d":"rente die je ook over eerder ontvangen rente krijgt"},{"t":"Enkelvoudige interest","d":"rente alleen over het oorspronkelijke bedrag"},{"t":"Sparen","d":"geld opzijzetten, vaak bij een bank tegen rente"},{"t":"Lenen","d":"geld tijdelijk van een ander gebruiken tegen rente"},{"t":"Hypotheek","d":"een lening voor een huis met het huis als onderpand"},{"t":"Centrale bank","d":"de bank die het geldbeleid van een land of de EU bepaalt"},{"t":"Rentestand","d":"de hoogte van de rente op een bepaald moment"},{"t":"Aflossing","d":"het terugbetalen van een lening"},{"t":"Onderpand","d":"bezit dat de bank mag verkopen als je niet terugbetaalt"},{"t":"Krediet","d":"de mogelijkheid om geld te lenen"},{"t":"Inflatie","d":"een algemene stijging van de prijzen"}],"sam":"<div class=\"sam-intro\">Wie geld leent of uitleent, betaalt of ontvangt <strong>rente</strong>. Bij <strong>samengestelde interest</strong> krijg je ook rente over eerder ontvangen rente. Een <strong>hypotheek</strong> is een lening voor een huis.</div><div class=\"sam-head\">1. Sparen, lenen en rente</div><p><strong>Rente</strong> is de vergoeding voor het gebruik van geld: je ontvangt rente over je <strong>sparen</strong> en betaalt rente als je gaat <strong>lenen</strong>. Een lening betaal je stapsgewijs terug via <strong>aflossing</strong>; de mogelijkheid om te lenen heet <strong>krediet</strong>.</p><div class=\"sam-head\">2. Rente over rente</div><p>Bij <strong>enkelvoudige interest</strong> krijg je elk jaar rente over alleen het startbedrag. Bij <strong>samengestelde interest</strong> krijg je rente over het bedrag inclusief de eerder bijgeschreven rente, waardoor je spaargeld sneller groeit.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Je zet € 100 weg tegen 10% rente per jaar. Hoeveel rente krijg je in het tweede jaar?</div><ol class=\"sam-worked-steps\"><li>Na jaar 1 heb je € 110 (€ 100 + € 10 rente).</li><li>In jaar 2 krijg je 10% over € 110, niet over € 100.</li></ol><div class=\"sam-worked-ans\">✅ € 11 rente: je krijgt rente over de rente (samengestelde interest).</div></div><div class=\"sam-head\">3. Lenen voor een huis</div><p>Een <strong>hypotheek</strong> is een lening voor een huis, met het huis als <strong>onderpand</strong>: betaal je niet terug, dan mag de bank het verkopen. De <strong>centrale bank</strong> bewaakt de waarde van het geld en beïnvloedt de rente.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rente</div><div class=\"sam-definitie-body\">de vergoeding voor het lenen of uitlenen van geld.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Samengestelde interest</div><div class=\"sam-definitie-body\">rente die je ook over eerder ontvangen rente krijgt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Enkelvoudige interest</div><div class=\"sam-definitie-body\">rente alleen over het oorspronkelijke bedrag.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sparen</div><div class=\"sam-definitie-body\">geld opzijzetten, vaak bij een bank tegen rente.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lenen</div><div class=\"sam-definitie-body\">geld tijdelijk van een ander gebruiken tegen rente.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Hypotheek</div><div class=\"sam-definitie-body\">een lening voor een huis met het huis als onderpand.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Centrale bank</div><div class=\"sam-definitie-body\">de bank die het geldbeleid van een land of de EU bepaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rentestand</div><div class=\"sam-definitie-body\">de hoogte van de rente op een bepaald moment.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Aflossing</div><div class=\"sam-definitie-body\">het terugbetalen van een lening.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Onderpand</div><div class=\"sam-definitie-body\">bezit dat de bank mag verkopen als je niet terugbetaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Krediet</div><div class=\"sam-definitie-body\">de mogelijkheid om geld te lenen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inflatie</div><div class=\"sam-definitie-body\">een algemene stijging van de prijzen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Rente»</b> is vergoeding voor geld, terwijl <b>«Aflossing»</b> lening terugbetalen is. <b>«Samengestelde interest»</b> is rente over rente, terwijl <b>«Enkelvoudige interest»</b> rente over startbedrag is. <b>«Sparen»</b> is geld opzijzetten, terwijl <b>«Lenen»</b> geld tijdelijk gebruiken is. <b>«Hypotheek»</b> is lening voor een huis, terwijl <b>«Krediet»</b> mogelijkheid om te lenen is.</div>"},"I":{"sv":[{"v":"Wat is een ondernemer?","o":["Iemand in loondienst","Iemand die een bedrijf start en risico neemt","Een klant","Een ambtenaar"],"c":1,"d":1,"u":"Iemand die een bedrijf start en risico neemt.","uo":["Dat is een werknemer.","Klopt: iemand die een bedrijf start en risico neemt.","Een klant koopt.","Iets anders."],"uh":"Iemand die een bedrijf start en risico neemt."},{"v":"Wat is een ondernemingsplan?","o":["Een belastingformulier","Een verzekering","Een plan waarin je je bedrijf uitwerkt","Een lening"],"c":2,"d":2,"u":"Een plan waarin je je bedrijf uitwerkt.","uo":["Nee, dat klopt niet.","Nee, dat klopt niet.","Klopt: een plan waarin je je bedrijf uitwerkt.","Nee, dat klopt niet."],"uh":"Een plan waarin je je bedrijf uitwerkt."},{"v":"Wat is startkapitaal?","o":["Geld om te beginnen","De latere winst","De belasting","Het loon"],"c":0,"d":1,"u":"Het geld dat je nodig hebt om te starten.","uo":["Klopt: het geld dat je nodig hebt om te starten.","Winst komt later.","Belasting is iets anders.","Loon is iets anders."],"uh":"Het geld dat je nodig hebt om te starten."},{"v":"Wat is marktonderzoek?","o":["Producten verkopen","Belasting berekenen","Loon uitbetalen","Onderzoek naar klanten en concurrenten"],"c":3,"d":2,"u":"Onderzoek naar je klanten en concurrenten.","uo":["Nee, dat klopt niet.","Nee, dat klopt niet.","Nee, dat klopt niet.","Klopt: onderzoek naar je klanten en concurrenten."],"uh":"Onderzoek naar je klanten en concurrenten."},{"v":"Wat is een doelgroep?","o":["Alle mensen","De klanten die je wilt bereiken","Je concurrenten","De overheid"],"c":1,"d":2,"u":"De groep klanten die je wilt bereiken.","uo":["Te breed.","Klopt: de groep klanten die je wilt bereiken.","Dat zijn juist rivalen.","Iets anders."],"uh":"De groep klanten die je wilt bereiken."},{"v":"Wat is een concurrent?","o":["Een klant","Een leverancier","Een ander bedrijf dat hetzelfde aanbiedt","De overheid"],"c":2,"d":2,"u":"Een rivaal die hetzelfde aanbiedt.","uo":["Een klant koopt.","Een leverancier levert.","Klopt: een rivaal die hetzelfde aanbiedt.","Iets anders."],"uh":"Een rivaal die hetzelfde aanbiedt."},{"v":"Wat is de kostprijs?","o":["De kosten per product","De verkoopprijs","De winst","De belasting"],"c":0,"d":2,"u":"De kosten per product.","uo":["Klopt: de kosten per product.","De prijs bij verkoop is iets anders.","Winst is iets anders.","Belasting is iets anders."],"uh":"De kosten per product."},{"v":"Wat is risico bij ondernemen?","o":["Zekere winst","Een verzekering","Een lening","De kans dat iets misgaat"],"c":3,"d":2,"u":"De kans dat iets misgaat en je geld verliest.","uo":["Winst is niet zeker.","Iets anders.","Iets anders.","Klopt: de kans dat iets misgaat en je geld verliest."],"uh":"De kans dat iets misgaat en je geld verliest."},{"v":"Wat is een investering?","o":["Geld weggooien","Geld uitgeven aan bedrijfsmiddelen","Belasting betalen","Sparen op de bank"],"c":1,"d":2,"u":"Geld uitgeven aan bedrijfsmiddelen.","uo":["Nee, dat klopt niet.","Klopt: geld uitgeven aan bedrijfsmiddelen.","Iets anders.","Iets anders."],"uh":"Geld uitgeven aan bedrijfsmiddelen."},{"v":"Wat is financiering?","o":["De winst","De belasting","Hoe je aan geld voor je bedrijf komt","De kostprijs"],"c":2,"d":2,"u":"De manier waarop je aan geld komt.","uo":["Winst is iets anders.","Belasting is iets anders.","Klopt: de manier waarop je aan geld komt.","Kostprijs is iets anders."],"uh":"De manier waarop je aan geld komt."},{"v":"Wat is de winstmarge?","o":["Verkoopprijs min kostprijs","De totale omzet","De belasting","Het startkapitaal"],"c":0,"d":2,"u":"Het verschil tussen verkoopprijs en kostprijs.","uo":["Klopt: het verschil tussen verkoopprijs en kostprijs.","Omzet is iets anders.","Belasting is iets anders.","Startkapitaal is iets anders."],"uh":"Het verschil tussen verkoopprijs en kostprijs."},{"v":"Wat is een rechtsvorm?","o":["Een verzekering","Een marktonderzoek","Een lening","De juridische vorm van een bedrijf"],"c":3,"d":3,"u":"De juridische vorm, zoals een eenmanszaak.","uo":["Nee, dat klopt niet.","Nee, dat klopt niet.","Nee, dat klopt niet.","Klopt: de juridische vorm, zoals een eenmanszaak."],"uh":"De juridische vorm, zoals een eenmanszaak."}],"begrippen":[{"t":"Ondernemer","d":"iemand die een bedrijf start en er risico mee neemt"},{"t":"Ondernemingsplan","d":"een plan waarin je je bedrijf uitwerkt"},{"t":"Startkapitaal","d":"het geld dat je nodig hebt om te beginnen"},{"t":"Investering","d":"geld dat je uitgeeft aan bedrijfsmiddelen"},{"t":"Marktonderzoek","d":"onderzoek naar klanten en concurrenten"},{"t":"Doelgroep","d":"de groep klanten die je wilt bereiken"},{"t":"Concurrent","d":"een ander bedrijf dat hetzelfde aanbiedt"},{"t":"Kostprijs","d":"de kosten per product"},{"t":"Winstmarge","d":"het verschil tussen verkoopprijs en kostprijs"},{"t":"Financiering","d":"de manier waarop je aan geld voor je bedrijf komt"},{"t":"Risico","d":"de kans dat iets misgaat en je geld verliest"},{"t":"Rechtsvorm","d":"de juridische vorm van een bedrijf, zoals een eenmanszaak"}],"sam":"<div class=\"sam-intro\">Een <strong>ondernemer</strong> start een bedrijf en neemt <strong>risico</strong>. In een <strong>ondernemingsplan</strong> werk je je idee uit: <strong>doelgroep</strong>, <strong>marktonderzoek</strong>, <strong>startkapitaal</strong> en de <strong>kostprijs</strong>.</div><div class=\"sam-head\">1. Een bedrijf starten</div><p>Een <strong>ondernemer</strong> begint een bedrijf en neemt daarbij <strong>risico</strong>: de kans dat het misgaat. In een <strong>ondernemingsplan</strong> werk je alles uit. Je hebt <strong>startkapitaal</strong> nodig en doet <strong>investeringen</strong> in bedrijfsmiddelen. Hoe je aan geld komt, heet de <strong>financiering</strong>; de <strong>rechtsvorm</strong> bepaalt onder meer wie aansprakelijk is.</p><div class=\"sam-head\">2. Klanten en prijs</div><p>Met <strong>marktonderzoek</strong> onderzoek je je klanten en <strong>concurrenten</strong>, zodat je je <strong>doelgroep</strong> kent. De <strong>kostprijs</strong> zijn de kosten per product; het verschil met de verkoopprijs is je <strong>winstmarge</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ondernemer</div><div class=\"sam-definitie-body\">iemand die een bedrijf start en er risico mee neemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ondernemingsplan</div><div class=\"sam-definitie-body\">een plan waarin je je bedrijf uitwerkt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Startkapitaal</div><div class=\"sam-definitie-body\">het geld dat je nodig hebt om te beginnen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Investering</div><div class=\"sam-definitie-body\">geld dat je uitgeeft aan bedrijfsmiddelen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Marktonderzoek</div><div class=\"sam-definitie-body\">onderzoek naar klanten en concurrenten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Doelgroep</div><div class=\"sam-definitie-body\">de groep klanten die je wilt bereiken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Concurrent</div><div class=\"sam-definitie-body\">een ander bedrijf dat hetzelfde aanbiedt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kostprijs</div><div class=\"sam-definitie-body\">de kosten per product.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Winstmarge</div><div class=\"sam-definitie-body\">het verschil tussen verkoopprijs en kostprijs.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Financiering</div><div class=\"sam-definitie-body\">de manier waarop je aan geld voor je bedrijf komt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Risico</div><div class=\"sam-definitie-body\">de kans dat iets misgaat en je geld verliest.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rechtsvorm</div><div class=\"sam-definitie-body\">de juridische vorm van een bedrijf, zoals een eenmanszaak.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Ondernemingsplan»</b> is plan voor je bedrijf, terwijl <b>«Marktonderzoek»</b> onderzoek naar de markt is. <b>«Startkapitaal»</b> is geld om te starten, terwijl <b>«Investering»</b> geld in bedrijfsmiddelen is. <b>«Marktonderzoek»</b> is onderzoek naar de markt, terwijl <b>«Doelgroep»</b> jouw klanten is. <b>«Doelgroep»</b> is jouw klanten, terwijl <b>«Concurrent»</b> rivaal op de markt is.</div>"}});